    private double AfternoonTeacherPercent => MorningTotalStudents == 0 ? 0 : Math.Round((double)MornigPresentTeachers / TotalTeachers * 100, 1);

    // ===== LOGIC BUỔI CHIỀU =====
    // Để hiển thị ổn định theo dữ liệu thật:
