    private async Task RefreshData()
    {
        await LoadData();
    }

    // === LOGIC LỊCH ===
    private bool IsCalendarModalOpen = false;
    private void OpenCalendarModal() => IsCalendarModalOpen = true;
    private void CloseCalendarModal() => IsCalendarModalOpen = false;

    private DateTime SelectedDate = DateTime.Today;
    private DateTime CurrentDisplayDate = new DateTime(DateTime.Today.Year, DateTime.Today.Month, 1);
    private List<DateTime> CalendarDays = new List<DateTime>();

    protected override void OnInitialized()
    {
        GenerateCalendar();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            try { await JS.InvokeVoidAsync("AppUtils.initCharts"); }
            catch { }

            // Load session để hiển thị tên user/trường trên banner
            currentSession = UserState.CurrentUser
                ?? await BrowserStorageService.GetUserSessionAsync(JSRuntime);

            maTruongBo = currentSession?.MaTruongBo
                ?? await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);

            // ── FIX RACE CONDITION ────────────────────────────────────────────
            // TopNavbar và Dashboard render song song → TopNavbar có thể chưa lưu
            // selectedNamHoc/selectedLevel vào localStorage khi Dashboard đọc.
            // Giải pháp: thử tối đa 3 lần, mỗi lần cách nhau 600ms.
            const int MAX_RETRIES = 3;
            for (int attempt = 1; attempt <= MAX_RETRIES; attempt++)
            {
                selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
                await LoadLevelFromStorage();

                if (!string.IsNullOrEmpty(selectedNamHoc) && !string.IsNullOrEmpty(selectedCapHoc))
                    break; // Có đủ dữ liệu → thoát vòng lặp

                if (attempt < MAX_RETRIES)
                {
                    // Chờ TopNavbar lưu xong rồi thử lại
                    await Task.Delay(600);
                }
            }

            await LoadData();
            isLoading = false;
            StateHasChanged();

            // ── LẮNG NGHE THAY ĐỔI TỪ TOPNAVBAR ────────────────────────────
            // Khi user đổi năm học / cấp học trên TopNavbar → tự reload dữ liệu
            try
            {
                var dotNetRef = DotNetObjectReference.Create(this);
                await JS.InvokeVoidAsync("eval", @"
                    (function(dotNetRef) {
                        window.__dashboardStorageListener = function(e) {
                            if (e.key === 'selectedNamHoc' || e.key === 'selectedLevel') {
                                dotNetRef.invokeMethodAsync('OnStorageChangedDashboard', e.key);
                            }
                        };
                        window.removeEventListener('storage', window.__dashboardStorageListener);
                        window.addEventListener('storage', window.__dashboardStorageListener);
                    })(dotNetRef);
                ", dotNetRef);
            }
            catch { }
        }
    }

    [JSInvokable]
    public async Task OnStorageChangedDashboard(string key)
    {
        // Khi TopNavbar thay đổi năm học hoặc cấp học → reload dữ liệu
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        await LoadLevelFromStorage();
        await LoadData();
        await InvokeAsync(StateHasChanged);
    }

    private async Task LoadLevelFromStorage()
    {
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        selectedTenCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevelText");
    }

    #region Load Thông Tin Thống Kê
    private async Task LoadData()
    {
        try
        {
            if (!string.IsNullOrEmpty(maTruongBo) &&
                !string.IsNullOrEmpty(selectedCapHoc) &&
                !string.IsNullOrEmpty(selectedNamHoc))
            {
                thongKeThongTinTruong = await DiemDanhServices.hGetThongKeDiemDanhTheoTruong(
                    maTruongBo,
                    selectedCapHoc,
                    selectedNamHoc,
                    SelectedDate,
                    null
                );
            }
            else
            {
                thongKeThongTinTruong = new ThongKeDiemDanh_DTO();
            }

            StateHasChanged();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi tải dữ liệu: {ex.Message}");
            thongKeThongTinTruong = new ThongKeDiemDanh_DTO();
            StateHasChanged();
        }
    }
    #endregion

    private void GenerateCalendar()
    {
        CalendarDays.Clear();
        var startOfMonth = new DateTime(CurrentDisplayDate.Year, CurrentDisplayDate.Month, 1);
        int daysToSubtract = (int)startOfMonth.DayOfWeek;
        var startDate = startOfMonth.AddDays(-daysToSubtract);

        for (int i = 0; i < 42; i++)
        {
            CalendarDays.Add(startDate.AddDays(i));
        }
    }

    private void PrevMonth()
    {
        CurrentDisplayDate = CurrentDisplayDate.AddMonths(-1);
        GenerateCalendar();
    }

    private void NextMonth()
    {
        CurrentDisplayDate = CurrentDisplayDate.AddMonths(1);
        GenerateCalendar();
    }

    private async Task SelectDate(DateTime date)
    {
        SelectedDate = date;
        CurrentDisplayDate = new DateTime(date.Year, date.Month, 1);
        GenerateCalendar();
        CloseCalendarModal();
        await LoadData();
    }

